(select jsonb_agg(jsonb_build_object('id',l.id,'q',l.original_quantity,'remaining',l.remaining_quantity,'price',l.unit_cost,'queue',l.queue_sequence,'at',e.event_at,'type',e.event_type) order by l.queue_sequence,e.event_at,l.id) from inventory_cost_layers l join inventory_cost_events e on e.id=l.source_event_id where l.item_name='하복 공팟 클리어' and e.event_at>='2026-07-22 00:00:00+09') layers,
(select jsonb_agg(jsonb_build_object('id',e.id,'ref',e.reference_id,'key',e.reference_line_key,'at',e.event_at,'q',e.quantity,'type',e.event_type,'alloc',(select jsonb_agg(jsonb_build_object('id',a.id,'layer',a.source_layer_id,'q',a.quantity,'price',a.unit_cost)) from inventory_cost_allocations a where a.outbound_event_id=e.id)) order by e.event_at,e.id) from inventory_cost_events e where e.item_name='하복 공팟 클리어' and e.direction='out' and e.metadata->>'restoredAt' is null and e.event_at>='2026-07-22 00:00:00+09') outs,
(select jsonb_agg(jsonb_build_object('id',l.id,'line',i.idx,'at',l.created_at,'q',(i.v->>'quantity')::int) order by l.created_at,l.id,i.idx) from logs l cross join lateral jsonb_array_elements(l.jsonb->'items') with ordinality i(v,idx) where l.category='stamp' and i.v->>'itemName'='하복 공팟 클리어' and i.v->>'remark' ~ '^서비스($|[,\s(])' and l.created_at>='2026-07-22 00:00:00+09') services,
(select jsonb_agg(to_jsonb(s)) from inventory_service_cost_links s join inventory_cost_allocations a on a.id=s.allocation_id join inventory_cost_layers x on x.id=a.source_layer_id where x.item_name='하복 공팟 클리어') links
union all
select '하복 0.6 코일' item,
(select jsonb_agg(jsonb_build_object('id',l.id,'q',l.original_quantity,'remaining',l.remaining_quantity,'price',l.unit_cost,'queue',l.queue_sequence,'at',e.event_at,'type',e.event_type) order by l.queue_sequence,e.event_at,l.id) from inventory_cost_layers l join inventory_cost_events e on e.id=l.source_event_id where l.item_name='하복 0.6 코일' and e.event_at>='2026-07-22 00:00:00+09') layers,
(select jsonb_agg(jsonb_build_object('id',e.id,'ref',e.reference_id,'key',e.reference_line_key,'at',e.event_at,'q',e.quantity,'type',e.event_type,'alloc',(select jsonb_agg(jsonb_build_object('id',a.id,'layer',a.source_layer_id,'q',a.quantity,'price',a.unit_cost)) from inventory_cost_allocations a where a.outbound_event_id=e.id)) order by e.event_at,e.id) from inventory_cost_events e where e.item_name='하복 0.6 코일' and e.direction='out' and e.metadata->>'restoredAt' is null and e.event_at>='2026-07-22 00:00:00+09') outs,
(select jsonb_agg(jsonb_build_object('id',l.id,'line',i.idx,'at',l.created_at,'q',(i.v->>'quantity')::int) order by l.created_at,l.id,i.idx) from logs l cross join lateral jsonb_array_elements(l.jsonb->'items') with ordinality i(v,idx) where l.category='stamp' and i.v->>'itemName'='하복 0.6 코일' and i.v->>'remark' ~ '^서비스($|[,\s(])' and l.created_at>='2026-07-22 00:00:00+09') services,
(select jsonb_agg(to_jsonb(s)) from inventory_service_cost_links s join inventory_cost_allocations a on a.id=s.allocation_id join inventory_cost_layers x on x.id=a.source_layer_id where x.item_name='하복 0.6 코일') links
union all
select '하부코일 1.6' item,
(select jsonb_agg(jsonb_build_object('id',l.id,'q',l.original_quantity,'remaining',l.remaining_quantity,'price',l.unit_cost,'queue',l.queue_sequence,'at',e.event_at,'type',e.event_type) order by l.queue_sequence,e.event_at,l.id) from inventory_cost_layers l join inventory_cost_events e on e.id=l.source_event_id where l.item_name='하부코일 1.6' and e.event_at>='2026-07-22 00:00:00+09') layers,
(select jsonb_agg(jsonb_build_object('id',e.id,'ref',e.reference_id,'key',e.reference_line_key,'at',e.event_at,'q',e.quantity,'type',e.event_type,'alloc',(select jsonb_agg(jsonb_build_object('id',a.id,'layer',a.source_layer_id,'q',a.quantity,'price',a.unit_cost)) from inventory_cost_allocations a where a.outbound_event_id=e.id)) order by e.event_at,e.id) from inventory_cost_events e where e.item_name='하부코일 1.6' and e.direction='out' and e.metadata->>'restoredAt' is null and e.event_at>='2026-07-22 00:00:00+09') outs,
(select jsonb_agg(jsonb_build_object('id',l.id,'line',i.idx,'at',l.created_at,'q',(i.v->>'quantity')::int) order by l.created_at,l.id,i.idx) from logs l cross join lateral jsonb_array_elements(l.jsonb->'items') with ordinality i(v,idx) where l.category='stamp' and i.v->>'itemName'='하부코일 1.6' and i.v->>'remark' ~ '^서비스($|[,\s(])' and l.created_at>='2026-07-22 00:00:00+09') services,
(select jsonb_agg(to_jsonb(s)) from inventory_service_cost_links s join inventory_cost_allocations a on a.id=s.allocation_id join inventory_cost_layers x on x.id=a.source_layer_id where x.item_name='하부코일 1.6') links
union all
select '젤로맥스 투명케이스' item,
(select jsonb_agg(jsonb_build_object('id',l.id,'q',l.original_quantity,'remaining',l.remaining_quantity,'price',l.unit_cost,'queue',l.queue_sequence,'at',e.event_at,'type',e.event_type) order by l.queue_sequence,e.event_at,l.id) from inventory_cost_layers l join inventory_cost_events e on e.id=l.source_event_id where l.item_name='젤로맥스 투명케이스' and e.event_at>='2026-07-22 00:00:00+09') layers,
(select jsonb_agg(jsonb_build_object('id',e.id,'ref',e.reference_id,'key',e.reference_line_key,'at',e.event_at,'q',e.quantity,'type',e.event_type,'alloc',(select jsonb_agg(jsonb_build_object('id',a.id,'layer',a.source_layer_id,'q',a.quantity,'price',a.unit_cost)) from inventory_cost_allocations a where a.outbound_event_id=e.id)) order by e.event_at,e.id) from inventory_cost_events e where e.item_name='젤로맥스 투명케이스' and e.direction='out' and e.metadata->>'restoredAt' is null and e.event_at>='2026-07-22 00:00:00+09') outs,
(select jsonb_agg(jsonb_build_object('id',l.id,'line',i.idx,'at',l.created_at,'q',(i.v->>'quantity')::int) order by l.created_at,l.id,i.idx) from logs l cross join lateral jsonb_array_elements(l.jsonb->'items') with ordinality i(v,idx) where l.category='stamp' and i.v->>'itemName'='젤로맥스 투명케이스' and i.v->>'remark' ~ '^서비스($|[,\s(])' and l.created_at>='2026-07-22 00:00:00+09') services,
(select jsonb_agg(to_jsonb(s)) from inventory_service_cost_links s join inventory_cost_allocations a on a.id=s.allocation_id join inventory_cost_layers x on x.id=a.source_layer_id where x.item_name='젤로맥스 투명케이스') links) q;
if current_data is distinct from (select jsonb_agg(v order by v->>'item') from jsonb_array_elements(expected) v) then raise exception '검증 이후 원가 원본 변경. 적용 중단'; end if;
before_state := jsonb_build_object('stock',(select md5(jsonb_agg(to_jsonb(b) order by item_name)::text) from inventory_balances b),'events',(select md5(jsonb_agg(to_jsonb(e) order by id)::text) from inventory_cost_events e),'layers',(select md5(jsonb_agg(to_jsonb(l) order by id)::text) from inventory_cost_layers l),'allocations',(select md5(jsonb_agg(to_jsonb(a) order by id)::text) from inventory_cost_allocations a));
for p in select value from jsonb_array_elements(plans) loop
ctx := get_service_cost_link_context((p->>'id')::bigint,(p->>'line')::int);
if ctx->>'item_name'<>p->>'name' or (ctx->>'quantity')::int<>(p->>'q')::int then raise exception '서비스 원본 불일치'; end if;
perform save_service_cost_links((p->>'id')::bigint,(p->>'line')::int,ctx->>'snapshot',p->'links','사용자 승인: 서비스 포함 시간순 FIFO 재계산으로 기존 출고의 층별 배정 및 최종 층별 잔량 일치 검증. 검증 원가 '||(p->>'cost')||'원 적용. 기존 소진 귀속만 반영, 재고·원가층 재차감 없음.');
if (select sum(s.quantity*a.unit_cost) from inventory_service_cost_links s join inventory_cost_allocations a on a.id=s.allocation_id where s.log_id=(p->>'id')::bigint and s.line_index=(p->>'line')::int) is distinct from (p->>'cost')::numeric then raise exception '반영 금액 불일치'; end if;
end loop;
after_state := jsonb_build_object('stock',(select md5(jsonb_agg(to_jsonb(b) order by item_name)::text) from inventory_balances b),'events',(select md5(jsonb_agg(to_jsonb(e) order by id)::text) from inventory_cost_events e),'layers',(select md5(jsonb_agg(to_jsonb(l) order by id)::text) from inventory_cost_layers l),'allocations',(select md5(jsonb_agg(to_jsonb(a) order by id)::text) from inventory_cost_allocations a));
if before_state is distinct from after_state then raise exception '재고 또는 원가 원본 변경. 전체 롤백'; end if;
end $apply$;
commit;
with actor as materialized(select set_config('request.jwt.claim.sub',(select id::text from users where oss_role='master' order by created_at limit 1),true))
select get_inventory_cost_integrity_report(1000)-'missingServiceLines' integrity,
(select count(distinct(log_id,line_index)) from inventory_service_cost_links) linked_lines,
(select sum(s.quantity*a.unit_cost) from inventory_service_cost_links s join inventory_cost_allocations a on a.id=s.allocation_id) linked_cost from actor;
